_SIGNALS = ("x", "y", "z")
_SOURCE_PATH_PARTS = 4
_VIBRATION_NDIM = 2

_ACCELERATION_SPEC = TimeSeriesSpec(
    spec_type="acceleration",
    name="Acceleration",
    unit_value=ureg.Unit("milligravity"),
